class ProviderUnavailable(ProviderError):
    """The provider cannot service the request (load/backend/handle failure).

    Surfaced as HTTP ``503`` / CLI exit code ``1``. The message is logged
    server-side; clients only ever see a generic status (handles and material
    never leave the boundary).
    """


class ProviderInvalidMaterial(ProviderError):
    """Material handed to the provider is malformed for the algorithm.

    Surfaced as HTTP ``400`` / CLI exit code ``2``; the message names the
    offending field but never embeds the material itself.
    """


class ProviderSwitchoverInvalid(ProviderError):
    """A switchover request names no usable chain target.

    Raised when no provider chain is configured or the requested
    ``provider_id`` is not one of the chain entries. Surfaced as HTTP
    ``400`` / CLI exit code ``2`` with the field named, and raised before
    any state write, provider swap or audit event (zero side effects).
    """


class MaterialTriple(NamedTuple):
    """The provider-owned result of generate/rotate/import_material."""

    handle: str
    public_key: Optional[str]
    encrypted_material: str


class ExportedMaterial(NamedTuple):
    """Result of export_material: material plus its public component."""

    public_key: Optional[str]
    encrypted_material: str


def _b64e(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64d(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def _require_triple(result, operation: str) -> MaterialTriple:
    """Validate a generate/rotate/import result has a handle and material."""
    if not isinstance(result, dict):
        raise ProviderUnavailable(
            "provider %s returned a non-object from %s"
            % ("external", operation)
        )
    handle = result.get("handle")
    material = result.get("encrypted_material")
    if not isinstance(handle, str) or not handle:
        raise ProviderUnavailable(
            "provider returned an empty handle from %s" % operation
        )
    if not isinstance(material, str) or not material:
        raise ProviderUnavailable(
            "provider returned empty encrypted_material from %s" % operation
        )
    public_key = result.get("public_key")
    if public_key is not None and not isinstance(public_key, str):
        raise ProviderUnavailable(
            "provider returned an invalid public_key from %s" % operation
        )
    return MaterialTriple(
        handle=handle, public_key=public_key, encrypted_material=material
    )


class KeyProvider:
    """Abstract provider; concrete providers implement the five operations."""

    provider_id = ""
    capabilities = {"algorithms": (), "operations": ()}

    def configure(self, data_dir: str) -> None:
        """Bind any persistent state to the data directory (optional)."""

    def generate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def rotate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def import_material(
        self,
        algorithm: str,
        public_key: Optional[str],
        material: str,
    ) -> MaterialTriple:
        raise NotImplementedError

    def export_material(self, handle: str) -> ExportedMaterial:
        raise NotImplementedError

    def delete(self, handle: str) -> None:
        raise NotImplementedError

    def sign(self, handle: str, message: bytes) -> bytes:
        """Optional KMS/HSM-native RSASSA-PKCS1-v1_5/SHA-256 signature.

        Contractual only when ``capabilities["operations"]`` declares
        ``"sign"``; then this MUST be implemented: ``handle`` must be a
        non-empty string (``ValueError`` otherwise), ``message`` must be
        bytes (``TypeError`` otherwise), an unknown or non-RSA handle and any
        backend failure raise :class:`ProviderUnavailable`, and a success
        returns the 256-byte signature. Private material never crosses the
        provider boundary.
        """
        raise NotImplementedError

    def unwrap_key(
        self, handle: str, wrapped_key: bytes, wrap_nonce=None
    ) -> bytes:
        """Optional KMS/HSM-native unwrap of an envelope data key.

        Contractual only when ``capabilities["operations"]`` declares
        ``"unwrap_key"``; then this MUST be implemented: ``handle`` must be a
        non-empty string (``ValueError`` otherwise), ``wrapped_key`` must be
        non-empty bytes and a non-null ``wrap_nonce`` must be bytes
        (``TypeError`` for a non-bytes value, ``ValueError`` for an empty
        ``wrapped_key``), an AES256 ``wrap_nonce`` must be exactly 12 bytes
        and an RSA2048 ``wrap_nonce`` must be null (``ValueError``
        otherwise), an unknown or algorithm-mismatched handle and any backend
        failure raise :class:`ProviderUnavailable`, an authentication failure
        raises :class:`ProviderInvalidMaterial`, and a success returns the
        32-byte data key. Private material never crosses the provider
        boundary.
        """
        raise NotImplementedError

    def wrap_key(self, handle: str, data_key: bytes) -> Tuple[bytes, Optional[bytes]]:
        """Optional KMS/HSM-native wrap of an envelope data key.

        Contractual only when ``capabilities["operations"]`` declares
        ``"wrap_key"``; then this MUST be implemented: ``handle`` must be a
        non-empty string (``ValueError`` otherwise), ``data_key`` must be
        bytes (``TypeError`` otherwise) and exactly 32 bytes (``ValueError``
        otherwise), an unknown or algorithm-mismatched handle and any backend
        failure raise :class:`ProviderUnavailable`, and a success returns
        ``(wrapped_key, wrap_nonce)`` -- a 48-byte wrapped key plus a 12-byte
        nonce for an AES256 KEK, or a 256-byte wrapped key plus ``None`` for
        an RSA2048 KEK. Private material never crosses the provider boundary.
        """
        raise NotImplementedError

    def rewrap_key(self, src: str, dst: str, envelope: bytes):
        """Optional KMS/HSM-native re-wrap of an envelope data key.

        Contractual only when ``capabilities["operations"]`` declares
        ``"rewrap_key"``; then this MUST be implemented: ``src`` and
        ``dst`` must be non-empty strings (``ValueError`` otherwise),
        ``envelope`` must be bytes (``TypeError`` otherwise) and non-empty
        with a valid ``keymgr-envelope-v1`` structure, algorithm and
        lengths (``ValueError`` otherwise). The method authenticates the
        wrapped data key and the content GCM tag inside the provider under
        the ``src`` handle's KEK and re-wraps the SAME data key under the
        ``dst`` handle's KEK; an authentication failure raises
        :class:`ProviderInvalidMaterial`, an unknown or
        algorithm-mismatched handle and any backend failure raise
        :class:`ProviderUnavailable`, and a success returns
        ``(wrapped_key, wrap_nonce)`` for the DST algorithm -- a 48-byte
        wrapped key plus a 12-byte nonce for AES256, or a 256-byte wrapped
        key plus ``None`` for RSA2048. The data key, the KEK private
        material and the plaintext never cross the provider boundary.
        """
        raise NotImplementedError

    def health(self) -> bool:
        """Optional KMS/HSM readiness probe.

        Built-in providers are always ready. An external provider may omit
        this method (a missing probe means healthy); :class:`_SafeProvider`
        enforces the bool/exception contract on objects that supply one.
        """
        return True

    def supports(self, algorithm: str, operation: str) -> bool:
        caps = getattr(self, "capabilities", {}) or {}
        return (
            algorithm in caps.get("algorithms", ())
            and operation in caps.get("operations", ())
        )


def _validate_external(obj) -> None:
    """Check a factory-built object satisfies the provider contract."""
    provider_id = getattr(obj, "provider_id", None)
    if not isinstance(provider_id, str) or not provider_id:
        raise ProviderUnavailable(
            "provider factory returned an object without a non-empty provider_id"
        )
    caps = getattr(obj, "capabilities", None)
    if not isinstance(caps, dict):
        raise ProviderUnavailable(
            "provider %r has no capabilities mapping" % provider_id
        )
    algorithms = caps.get("algorithms")
    operations = caps.get("operations")
    if not isinstance(algorithms, (list, tuple)) or not isinstance(
        operations, (list, tuple)
    ):
        raise ProviderUnavailable(
            "provider %r capabilities must list algorithms and operations"
            % provider_id
        )
    missing = [a for a in SUPPORTED_ALGORITHMS if a not in algorithms]
    if missing:
        raise ProviderUnavailable(
            "provider %r lacks required algorithms: %s"
            % (provider_id, ", ".join(missing))
        )
    missing_ops = [op for op in OPERATIONS if op not in operations]
    if missing_ops:
        raise ProviderUnavailable(
            "provider %r lacks required operations: %s"
            % (provider_id, ", ".join(missing_ops))
        )
    for name in OPERATIONS:
        if not callable(getattr(obj, name, None)):
            raise ProviderUnavailable(
                "provider %r is missing a callable %s() operation"
                % (provider_id, name)
            )
    # ``sign`` is optional, but declaring it makes the method contractual: a
    # provider listing it without a callable sign() is invalid.
    if OP_SIGN in operations and not callable(getattr(obj, "sign", None)):
        raise ProviderUnavailable(
            "provider %r declares the sign operation without a callable "
            "sign() method" % provider_id
        )
    # ``unwrap_key`` is optional under the same rule: declaring it makes a
    # callable unwrap_key() method contractual.
    if OP_UNWRAP_KEY in operations and not callable(
        getattr(obj, "unwrap_key", None)
    ):
        raise ProviderUnavailable(
            "provider %r declares the unwrap_key operation without a "
            "callable unwrap_key() method" % provider_id
        )
    # ``wrap_key`` is optional under the same rule: declaring it makes a
    # callable wrap_key() method contractual.
    if OP_WRAP_KEY in operations and not callable(
        getattr(obj, "wrap_key", None)
    ):
        raise ProviderUnavailable(
            "provider %r declares the wrap_key operation without a "
            "callable wrap_key() method" % provider_id
        )
    # ``rewrap_key`` is optional under the same rule: declaring it makes a
    # callable rewrap_key() method contractual.
    if OP_REWRAP_KEY in operations and not callable(
        getattr(obj, "rewrap_key", None)
    ):
        raise ProviderUnavailable(
            "provider %r declares the rewrap_key operation without a "
            "callable rewrap_key() method" % provider_id
        )
    configure = getattr(obj, "configure", None)
    if configure is not None and not callable(configure):
        raise ProviderUnavailable(
            "provider %r has a non-callable configure attribute" % provider_id
        )
    # health() is optional: no attribute means always healthy. A present but
    # non-callable health is a contract failure like any other method.
    health = getattr(obj, "health", None)
    if health is not None and not callable(health):
        raise ProviderUnavailable(
            "provider %r has a non-callable health attribute" % provider_id
        )


class _SafeProvider:
    """Adapter around an external provider enforcing the error contract.

    ProviderError subtypes pass through unchanged; any other exception the
    external module raises is normalized to ProviderUnavailable so a backend
    fault always surfaces as 503 and never as a 500 or a fallback.
    """

    def __init__(self, inner) -> None:
        self._inner = inner
        self.provider_id = inner.provider_id
        self.capabilities = inner.capabilities

    def configure(self, data_dir: str) -> None:
        try:
            configure = getattr(self._inner, "configure", None)
            if configure is not None:
                configure(data_dir)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r failed to initialize" % self.provider_id
            ) from exc

    def _call(self, name: str, *args):
        method = getattr(self._inner, name)
        try:
            return method(*args)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r operation %s failed" % (self.provider_id, name)
            ) from exc

    def generate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("generate", algorithm), "generate")

    def rotate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("rotate", algorithm), "rotate")

    def import_material(self, algorithm, public_key, material) -> MaterialTriple:
        return _require_triple(
            self._call("import_material", algorithm, public_key, material),
            "import_material",
        )

    def export_material(self, handle: str) -> ExportedMaterial:
        result = self._call("export_material", handle)
        if not isinstance(result, dict):
            raise ProviderUnavailable(
                "provider returned a non-object from export_material"
            )
        material = result.get("encrypted_material")
        if not isinstance(material, str) or not material:
            raise ProviderUnavailable(
                "provider returned empty encrypted_material from export_material"
            )
        public_key = result.get("public_key")
        if public_key is not None and not isinstance(public_key, str):
            raise ProviderUnavailable(
                "provider returned an invalid public_key from export_material"
            )
        return ExportedMaterial(
            public_key=public_key, encrypted_material=material
        )

    def delete(self, handle: str) -> None:
        # Idempotent by contract; even so, a backend fault on delete is a 503
        # (the caller may retry, and delete must remain idempotent).
        self._call("delete", handle)

    def sign(self, handle: str, message: bytes) -> bytes:
        """KMS/HSM-native sign, with the error contract enforced.

        Only invoked when the provider declared ``sign`` (contract validation
        guarantees a callable method then); a backend fault is normalized to
        :class:`ProviderUnavailable` like every other operation, and a result
        that is not bytes is a contract failure, never passed on.
        """
        if not callable(getattr(self._inner, "sign", None)):
            raise ProviderUnavailable(
                "provider %r declares sign without a callable sign() method"
                % self.provider_id
            )
        result = self._call("sign", handle, message)
        if not isinstance(result, bytes):
            raise ProviderUnavailable(
                "provider returned a non-bytes signature from sign"
            )
        return result

    def unwrap_key(self, handle: str, wrapped_key: bytes, wrap_nonce=None) -> bytes:
        """KMS/HSM-native DEK unwrap, with the error contract enforced.

        Only invoked when the provider declared ``unwrap_key`` (contract
        validation guarantees a callable method then). The boundary argument
        rules are enforced here too, so a provider cannot silently accept a
        malformed call: a bad handle is a ``ValueError`` and a non-bytes
        ``wrapped_key``/non-null non-bytes ``wrap_nonce`` a ``TypeError``,
        exactly as the contract requires of the method itself. The
        algorithm-specific nonce rules stay with the provider (only it knows
        the handle's algorithm). ``ValueError``/``TypeError``/
        :class:`ProviderError` from the provider pass through unchanged (an
        authentication failure surfaces as :class:`ProviderInvalidMaterial`);
        any other exception is a backend fault normalized to
        :class:`ProviderUnavailable`, and a result that is not exactly the
        32-byte data key is a contract failure, never passed on.
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("unwrap_key requires a non-empty handle string")
        if not isinstance(wrapped_key, bytes):
            raise TypeError("unwrap_key wrapped_key must be bytes")
        if wrap_nonce is not None and not isinstance(wrap_nonce, bytes):
            raise TypeError("unwrap_key wrap_nonce must be bytes or None")
        if not wrapped_key:
            raise ValueError("unwrap_key wrapped_key must be non-empty")

        if not callable(getattr(self._inner, "unwrap_key", None)):
            raise ProviderUnavailable(
                "provider %r declares unwrap_key without a callable "
                "unwrap_key() method" % self.provider_id
            )
        try:
            result = self._inner.unwrap_key(handle, wrapped_key, wrap_nonce)
        except (ValueError, TypeError, ProviderError):
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r operation unwrap_key failed" % self.provider_id
            ) from exc
        if not isinstance(result, bytes) or len(result) != _DEK_LEN:
            raise ProviderUnavailable(
                "provider returned a malformed data key from unwrap_key"
            )
        return result

    def wrap_key(self, handle: str, data_key: bytes):
        """KMS/HSM-native DEK wrap, with the error contract enforced.

        Only invoked when the provider declared ``wrap_key`` (contract
        validation guarantees a callable method then). The boundary argument
        rules are enforced here too: a bad handle is a ``ValueError`` and a
        non-bytes or non-32-byte ``data_key`` is a ``TypeError``/
        ``ValueError``, exactly as the contract requires of the method
        itself. ``ValueError``/``TypeError``/:class:`ProviderError` from the
        provider pass through unchanged; any other exception is a backend
        fault normalized to :class:`ProviderUnavailable`. A result that is not
        a two-element tuple of ``(bytes, bytes | None)`` is a contract
        failure; the algorithm-specific lengths (48/12 for AES256,
        256/None for RSA2048) are enforced by the envelope caller, which is
        the only layer that knows the handle's algorithm.
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("wrap_key requires a non-empty handle string")
        if not isinstance(data_key, bytes):
            raise TypeError("wrap_key data_key must be bytes")
        if len(data_key) != _DEK_LEN:
            raise ValueError("wrap_key data_key must be 32 bytes")
        if not callable(getattr(self._inner, "wrap_key", None)):
            raise ProviderUnavailable(
                "provider %r declares wrap_key without a callable "
                "wrap_key() method" % self.provider_id
            )
        try:
            result = self._inner.wrap_key(handle, data_key)
        except (ValueError, TypeError, ProviderError):
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r operation wrap_key failed" % self.provider_id
            ) from exc
        if (
            not isinstance(result, tuple)
            or len(result) != 2
            or not isinstance(result[0], bytes)
            or not result[0]
            or (result[1] is not None and not isinstance(result[1], bytes))
        ):
            raise ProviderUnavailable(
                "provider returned a malformed wrap result from wrap_key"
            )
        return result

    def rewrap_key(self, src: str, dst: str, envelope: bytes):
        """KMS/HSM-native envelope rewrap, with the error contract enforced.

        Only invoked when the provider declared ``rewrap_key`` (contract
        validation guarantees a callable method then). The boundary argument
        rules are enforced here too, so a provider cannot silently accept a
        malformed call: a bad ``src``/``dst`` handle is a ``ValueError`` and
        a non-bytes or empty ``envelope`` a ``TypeError``/``ValueError``,
        exactly as the contract requires of the method itself. The structural
        envelope rules stay with the provider (only it can authenticate the
        payload). ``ValueError``/``TypeError``/:class:`ProviderError` from
        the provider pass through unchanged (an authentication failure
        surfaces as :class:`ProviderInvalidMaterial`); any other exception is
        a backend fault normalized to :class:`ProviderUnavailable`, and a
        result that is not a two-element tuple of ``(bytes, bytes | None)``
        is a contract failure, never passed on. The algorithm-specific
        lengths (48/12 for an AES256 target, 256/None for RSA2048) are
        enforced by the envelope caller, which is the only layer that knows
        the target version's algorithm.
        """
        if not isinstance(src, str) or not src:
            raise ValueError("rewrap_key requires a non-empty src handle string")
        if not isinstance(dst, str) or not dst:
            raise ValueError("rewrap_key requires a non-empty dst handle string")
        if not isinstance(envelope, bytes):
            raise TypeError("rewrap_key envelope must be bytes")
        if not envelope:
            raise ValueError("rewrap_key envelope must be non-empty")
        if not callable(getattr(self._inner, "rewrap_key", None)):
            raise ProviderUnavailable(
                "provider %r declares rewrap_key without a callable "
                "rewrap_key() method" % self.provider_id
            )
        try:
            result = self._inner.rewrap_key(src, dst, envelope)
        except (ValueError, TypeError, ProviderError):
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r operation rewrap_key failed" % self.provider_id
            ) from exc
        if (
            not isinstance(result, tuple)
            or len(result) != 2
            or not isinstance(result[0], bytes)
            or not result[0]
            or (result[1] is not None and not isinstance(result[1], bytes))
        ):
            raise ProviderUnavailable(
                "provider returned a malformed wrap result from rewrap_key"
            )
        return result

    def health(self) -> bool:
        """Optional readiness probe normalized to a bool.

        A provider without a ``health`` method is treated as ready. A method
        that raises, returns a non-bool, or returns ``False`` reports
        unavailable; any backend text is swallowed here and never reaches a
        client.
        """
        method = getattr(self._inner, "health", None)
        if method is None:
            # Missing health() means healthy by contract.
            return True
        try:
            result = method()
        except Exception:
            return False
        # Only the exact bool True is healthy; a bool False, a truthy
        # non-bool (1, "yes", ...) and any other object mean unavailable.
        return result is True


def declares_sign(provider) -> bool:
    """Whether a bound provider declares the optional ``sign`` operation.

    Declaration is purely by ``capabilities["operations"]`` containing
    ``"sign"``: a declaring external provider was contract-validated to have
    a callable ``sign`` method, and the built-in local provider always
    declares and implements it. Anything else (including a provider whose
    capabilities are not a mapping) keeps the export-based signing path.
    """
    caps = getattr(provider, "capabilities", None)
    if not isinstance(caps, dict):
        return False
    operations = caps.get("operations")
    if not isinstance(operations, (list, tuple)):
        return False
    return OP_SIGN in operations


def declares_unwrap_key(provider) -> bool:
    """Whether a bound provider declares the optional ``unwrap_key`` operation.

    Declaration is purely by ``capabilities["operations"]`` containing
    ``"unwrap_key"``: a declaring external provider was contract-validated to
    have a callable ``unwrap_key`` method, and the built-in local provider
    always declares and implements it. Anything else (including a provider
    whose capabilities are not a mapping) keeps the export-based decrypt
    path.
    """
    caps = getattr(provider, "capabilities", None)
    if not isinstance(caps, dict):
        return False
    operations = caps.get("operations")
    if not isinstance(operations, (list, tuple)):
        return False
    return OP_UNWRAP_KEY in operations


def declares_wrap_key(provider) -> bool:
    """Whether a bound provider declares the optional ``wrap_key`` operation.

    Declaration is purely by ``capabilities["operations"]`` containing
    ``"wrap_key"``: a declaring external provider was contract-validated to
    have a callable ``wrap_key`` method, and the built-in local provider
    always declares and implements it. Anything else (including a provider
    whose capabilities are not a mapping) keeps the export-based encrypt
    path.
    """
    caps = getattr(provider, "capabilities", None)
    if not isinstance(caps, dict):
        return False
    operations = caps.get("operations")
    if not isinstance(operations, (list, tuple)):
        return False
    return OP_WRAP_KEY in operations


def declares_rewrap_key(provider) -> bool:
    """Whether a bound provider declares the optional ``rewrap_key`` operation.

    Declaration is purely by ``capabilities["operations"]`` containing
    ``"rewrap_key"``: a declaring external provider was contract-validated to
    have a callable ``rewrap_key`` method, and the built-in local provider
    always declares and implements it. Anything else (including a provider
    whose capabilities are not a mapping) keeps the export-based rewrap
    path.
    """
    caps = getattr(provider, "capabilities", None)
    if not isinstance(caps, dict):
        return False
    operations = caps.get("operations")
    if not isinstance(operations, (list, tuple)):
        return False
    return OP_REWRAP_KEY in operations


class LocalProvider(KeyProvider):
    """Built-in software provider.

    Raw material never lands in a key file: each generated/imported key is
    wrapped with AES-256-GCM under a data-encryption key kept in
    ``local.dek`` (0600), and only the wrapped blob plus an opaque handle is
    persisted. A small registry (``local-registry.json``, 0600) maps each
    handle to its algorithm and wrapped blob, so ``export_material(handle)``
    can re-derive the raw material and ``delete`` stays idempotent. The
    registry stores only DEK-wrapped material, never plaintext.
    """

    provider_id = LOCAL_PROVIDER_ID
    capabilities = {
        "algorithms": tuple(SUPPORTED_ALGORITHMS),
        # The local provider declares and implements the optional native
        # ``sign``, ``unwrap_key``, ``wrap_key`` and ``rewrap_key``
        # operations: signing and native DEK wrapping/unwrapping/rewrapping
        # happen inside the provider and the unwrapped private key never
        # crosses the boundary.
        "operations": OPERATIONS + (
            OP_SIGN,
            OP_UNWRAP_KEY,
            OP_WRAP_KEY,
            OP_REWRAP_KEY,
        ),
    }

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._data_dir: Optional[str] = None
        self._dek: Optional[bytes] = None
        self._registry: dict = {}
        self._configured = False

    # -- state -------------------------------------------------------------
    def configure(self, data_dir: str) -> None:
        with self._lock:
            if self._configured and self._data_dir == data_dir:
                return
            os.makedirs(data_dir, exist_ok=True)
            self._data_dir = data_dir
            self._dek = self._load_or_create_dek(data_dir)
            self._registry = self._load_registry(data_dir)
            self._configured = True

    @staticmethod
    def _load_or_create_dek(data_dir: str) -> bytes:
        path = os.path.join(data_dir, _DEK_NAME)
        try:
            with open(path, "rb") as fh:
                dek = fh.read()
            if len(dek) == 32:
                return dek
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise ProviderUnavailable("cannot read local DEK: %s" % exc) from exc
        dek = os.urandom(32)
        try:
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            try:
                os.write(fd, dek)
                os.fsync(fd)
            finally:
                os.close(fd)
        except FileExistsError:
            with open(path, "rb") as fh:
                dek = fh.read()
        except OSError as exc:
            raise ProviderUnavailable("cannot write local DEK: %s" % exc) from exc
        if len(dek) != 32:
            raise ProviderUnavailable("local DEK file is corrupt")
        return dek

    @staticmethod
    def _load_registry(data_dir: str) -> dict:
        path = os.path.join(data_dir, _REGISTRY_NAME)
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except FileNotFoundError:
            return {}
        except (OSError, ValueError) as exc:
            raise ProviderUnavailable(
                "cannot read local handle registry: %s" % exc
            ) from exc
        if not isinstance(data, dict):
            raise ProviderUnavailable("local handle registry is corrupt")
        return data

    def _persist_registry_locked(self) -> None:
        path = os.path.join(self._data_dir, _REGISTRY_NAME)
        fd, tmp_path = tempfile.mkstemp(dir=self._data_dir, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(self._registry, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _require_configured(self) -> None:
        if not self._configured:
            raise ProviderUnavailable("local provider is not configured")

    # -- wrapping ----------------------------------------------------------
    def _wrap_locked(self, raw_material: str) -> str:
        nonce = os.urandom(_NONCE_LEN)
        ct = AESGCM(self._dek).encrypt(
            nonce, raw_material.encode("utf-8"), None
        )
        return _WRAP_PREFIX + _b64e(nonce) + "." + _b64e(ct)

    def _unwrap_locked(self, blob: str) -> str:
        if not isinstance(blob, str) or not blob.startswith(_WRAP_PREFIX):
            raise ProviderUnavailable("stored material is not a local blob")
        try:
            nonce_b, ct_b = blob[len(_WRAP_PREFIX):].split(".", 1)
            nonce = _b64d(nonce_b)
            ct = _b64d(ct_b)
            raw = AESGCM(self._dek).decrypt(nonce, ct, None)
            return raw.decode("utf-8")
        except Exception as exc:
            raise ProviderUnavailable(
                "cannot unwrap local material"
            ) from exc

    # -- material validation ----------------------------------------------
    @staticmethod
    def _validate_material(
        algorithm: str, public_key, material
    ):
        """Validate raw (legacy-shaped) material for an algorithm.

        AES material is base64 of exactly 32 bytes and has no public part;
        RSA material is a PEM private key of exactly 2048 bits, and the
        supplied public key (when present) must match it. Returns the parsed
        RSA private key (None for AES).
        """
        if not isinstance(material, str) or not material:
            raise ProviderInvalidMaterial(
                "field encrypted_material must be a non-empty string"
            )
        if algorithm == "AES256":
            if public_key is not None:
                raise ProviderInvalidMaterial(
                    "field public_key must be null for AES256"
                )
            try:
                raw = base64.b64decode(material, validate=True)
            except (ValueError, TypeError) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be valid base64 for AES256"
                ) from exc
            if len(raw) != 32:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must decode to 32 bytes for AES256"
                )
            return None
        if algorithm == "RSA2048":
            try:
                private_key = serialization.load_pem_private_key(
                    material.encode("utf-8"), password=None
                )
            except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a PEM private key for RSA2048"
                ) from exc
            if not isinstance(private_key, rsa.RSAPrivateKey) or (
                private_key.key_size != 2048
            ):
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a 2048-bit RSA private key"
                )
            if public_key is not None:
                if not isinstance(public_key, str) or not public_key:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM string for RSA2048"
                    )
                try:
                    supplied = serialization.load_pem_public_key(
                        public_key.encode("utf-8")
                    )
                    if not isinstance(supplied, rsa.RSAPublicKey):
                        raise ValueError("not an RSA public key")
                except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM RSA public key"
                    ) from exc
                expected = private_key.public_key().public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                actual = supplied.public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                if expected != actual:
                    raise ProviderInvalidMaterial(
                        "field public_key does not match the private key"
                    )
            return private_key
        raise ProviderInvalidMaterial(
            "unsupported value for field algorithm: %r (supported: %s)"
            % (algorithm, ", ".join(SUPPORTED_ALGORITHMS))
        )

    @staticmethod
    def _public_pem(private_key) -> str:
        return private_key.public_key().public_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PublicFormat.SubjectPublicKeyInfo,
        ).decode("ascii")

    def _adopt(
        self,
        algorithm: str,
        public_key,
        raw_material: str,
    ) -> MaterialTriple:
        """Validate raw material, wrap it under the DEK, mint a handle."""
        self._require_configured()
        private_key = self._validate_material(algorithm, public_key, raw_material)
        if algorithm == "RSA2048" and public_key is None:
            public_key = self._public_pem(private_key)
        handle = uuid.uuid4().hex
        with self._lock:
            wrapped = self._wrap_locked(raw_material)

            wrapped = self._wrap_locked(raw_material)
            self._registry[handle] = {
                "algorithm": algorithm,
                "wrapped": wrapped,
            }
            self._persist_registry_locked()
        return MaterialTriple(
            handle=handle,
            public_key=public_key,
            encrypted_material=wrapped,
        )

    # -- KeyProvider operations -------------------------------------------
    def generate(self, algorithm: str) -> MaterialTriple:
        generated = generate_key(algorithm)
        return self._adopt(
            algorithm, generated.public_material, generated.private_material
        )

    def rotate(self, algorithm: str) -> MaterialTriple:
        # A rotated version is brand-new material owned by the same provider.
        return self.generate(algorithm)

    def import_material(
        self,
        algorithm: str,
        public_key,
        material: str,
    ) -> MaterialTriple:
        return self._adopt(algorithm, public_key, material)

    def export_material(self, handle: str) -> ExportedMaterial:
        """Return the raw bundle-shaped material for a registered handle.

        The registry keeps the DEK-wrapped blob, which is unwrapped here. The
        returned material is only ever sealed inside a passphrase-encrypted
        export bundle; an unknown handle is ProviderUnavailable.
        """
        self._require_configured()
        if not isinstance(handle, str) or not handle:
            raise ProviderUnavailable("export_material requires a handle")
        with self._lock:
            meta = self._registry.get(handle)
            if meta is None:
                raise ProviderUnavailable("unknown handle")
            algorithm = meta.get("algorithm")
            blob = meta.get("wrapped")
            try:
                raw = self._unwrap_locked(blob)
            except ProviderUnavailable:
                raise
        if algorithm == "AES256":
            return ExportedMaterial(public_key=None, encrypted_material=raw)
        try:
            private_key = serialization.load_pem_private_key(
                raw.encode("utf-8"), password=None
            )
        except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
            raise ProviderUnavailable("stored local material is corrupt") from exc
        return ExportedMaterial(
            public_key=self._public_pem(private_key),
            encrypted_material=raw,
        )

    def delete(self, handle: str) -> None:
        """Drop a handle from the registry. Idempotent and never fails 404."""
        self._require_configured()
        with self._lock:
            if handle in self._registry:
                del self._registry[handle]
                self._persist_registry_locked()

    def sign(self, handle: str, message: bytes) -> bytes:
        """Sign ``message`` with a registered RSA2048 handle, in-provider.

        The wrapped private key is unwrapped inside the provider and never
        returned: only the 256-byte RSASSA-PKCS1-v1_5/SHA-256 signature
        crosses the boundary. A handle that is not a non-empty string is a
        ``ValueError``, a non-bytes message a ``TypeError``; an unknown or
        non-RSA handle (or corrupt stored material) is
        :class:`ProviderUnavailable`.
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("sign requires a non-empty handle string")
        if not isinstance(message, bytes):
            raise TypeError("sign message must be bytes")
        self._require_configured()
        with self._lock:
            meta = self._registry.get(handle)
            if meta is None:
                raise ProviderUnavailable("unknown handle")
            if meta.get("algorithm") != "RSA2048":
                raise ProviderUnavailable(
                    "handle does not belong to an RSA2048 key"
                )
            raw = self._unwrap_locked(meta.get("wrapped"))
        try:
            private_key = signing_mod.load_rsa_private_key(raw)
        except signing_mod.SigningError as exc:
            raise ProviderUnavailable(
                "stored local material is corrupt"
            ) from exc
        return signing_mod.rsa_sign(private_key, message)

    # -- native DEK wrap/unwrap/rewrap --------------------------------------
    @staticmethod
    def _unwrap_dek_material(
        algorithm: str, raw: str, wrapped_key: bytes, wrap_nonce
    ) -> bytes:
        """Unwrap a 32-byte envelope DEK under unwrapped KEK material.

        Shared by ``unwrap_key`` and ``rewrap_key``: the algorithm-specific
        nonce rules are ``ValueError``, corrupt stored material is
        :class:`ProviderUnavailable`, and an authentication failure (AES-GCM
        tag or RSA-OAEP padding) or a DEK that is not exactly 32 bytes is
        :class:`ProviderInvalidMaterial`.
        """
        if algorithm == "AES256":
            if wrap_nonce is None or len(wrap_nonce) != _NONCE_LEN:
                raise ValueError(
                    "unwrap_key wrap_nonce must be 12 bytes for AES256"
                )
            try:
                kek = base64.b64decode(raw.encode("ascii"), validate=True)
            except (ValueError, TypeError) as exc:
                raise ProviderUnavailable(
                    "stored local material is corrupt"
                ) from exc
            if len(kek) != 32:
                raise ProviderUnavailable("stored local material is corrupt")
            try:
                dek = AESGCM(kek).decrypt(wrap_nonce, wrapped_key, None)
            except InvalidTag as exc:
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        elif algorithm == "RSA2048":
            if wrap_nonce is not None:
                raise ValueError(
                    "unwrap_key wrap_nonce must be null for RSA2048"
                )
            try:
                private_key = signing_mod.load_rsa_private_key(raw)
            except signing_mod.SigningError as exc:
                raise ProviderUnavailable(
                    "stored local material is corrupt"
                ) from exc
            try:
                dek = private_key.decrypt(wrapped_key, _OAEP)
            except ValueError as exc:
                # RSA-OAEP decryption failures (wrong key/padding) land here.
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        else:
            raise ProviderUnavailable(
                "handle does not belong to a supported algorithm"
            )
        if len(dek) != _DEK_LEN:
            # Authenticated but not a 32-byte data key: the wrapped blob was
            # never a keymgr-envelope-v1 DEK wrap.
            raise ProviderInvalidMaterial(
                "unwrapped data key must be 32 bytes"
            )
        return dek

    @staticmethod
    def _wrap_dek_material(algorithm: str, raw: str, data_key: bytes):
        """Wrap a 32-byte DEK under unwrapped KEK material.

        Shared by ``wrap_key`` and ``rewrap_key``: AES256 yields the 48-byte
        AES-256-GCM sealed key and a 12-byte nonce, RSA2048 the 256-byte
        RSA-OAEP-SHA256 sealed key and ``None``; corrupt stored material is
        :class:`ProviderUnavailable`.
        """
        if algorithm == "AES256":
            try:
                kek = base64.b64decode(raw.encode("ascii"), validate=True)
            except (ValueError, TypeError) as exc:
                raise ProviderUnavailable(
                    "stored local material is corrupt"
                ) from exc
            if len(kek) != 32:
                raise ProviderUnavailable("stored local material is corrupt")
            wrap_nonce = os.urandom(_NONCE_LEN)
            wrapped = AESGCM(kek).encrypt(wrap_nonce, data_key, None)
            return wrapped, wrap_nonce
        if algorithm == "RSA2048":
            try:
                private_key = signing_mod.load_rsa_private_key(raw)
            except signing_mod.SigningError as exc:
                raise ProviderUnavailable(
                    "stored local material is corrupt"
                ) from exc
            wrapped = private_key.public_key().encrypt(data_key, _OAEP)
            return wrapped, None
        raise ProviderUnavailable(
            "handle does not belong to a supported algorithm"
        )

    def unwrap_key(self, handle: str, wrapped_key: bytes, wrap_nonce=None) -> bytes:
        """Unwrap a ``keymgr-envelope-v1`` data key under a registered handle.

        The wrapped KEK material is unwrapped inside the provider and never
        returned: only the 32-byte data key crosses the boundary. A handle
        that is not a non-empty string is a ``ValueError``; a non-bytes
        ``wrapped_key`` or a non-null non-bytes ``wrap_nonce`` is a
        ``TypeError``; an empty ``wrapped_key``, an AES256 ``wrap_nonce``
        that is not exactly 12 bytes or an RSA2048 ``wrap_nonce`` that is not
        null is a ``ValueError``; an unknown handle (or corrupt stored
        material) is :class:`ProviderUnavailable`; a wrapped key that fails
        authentication (AES-GCM tag or RSA-OAEP padding) is
        :class:`ProviderInvalidMaterial`.
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("unwrap_key requires a non-empty handle string")
        if not isinstance(wrapped_key, bytes):
            raise TypeError("unwrap_key wrapped_key must be bytes")
        if wrap_nonce is not None and not isinstance(wrap_nonce, bytes):
            raise TypeError("unwrap_key wrap_nonce must be bytes or None")
        if not wrapped_key:
            raise ValueError("unwrap_key wrapped_key must be non-empty")
        self._require_configured()
        with self._lock:
            meta = self._registry.get(handle)
            if meta is None:
                raise ProviderUnavailable("unknown handle")
            algorithm = meta.get("algorithm")
            raw = self._unwrap_locked(meta.get("wrapped"))
        return self._unwrap_dek_material(
            algorithm, raw, wrapped_key, wrap_nonce
        )

    def wrap_key(self, handle: str, data_key: bytes):
        """Wrap a 32-byte data key under a registered handle, in-provider.

        The wrapped KEK material is unwrapped inside the provider and never
        returned: only the ``(wrapped_key, wrap_nonce)`` pair crosses the
        boundary -- AES256 yields a 48-byte AES-256-GCM sealed key and a
        12-byte nonce, RSA2048 a 256-byte RSA-OAEP-SHA256 sealed key and
        ``None``. A handle that is not a non-empty string is a ``ValueError``;
        a non-bytes ``data_key`` a ``TypeError`` and a non-32-byte one a
        ``ValueError``; an unknown handle (or corrupt stored material) is
        :class:`ProviderUnavailable`.
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("wrap_key requires a non-empty handle string")
        if not isinstance(data_key, bytes):
            raise TypeError("wrap_key data_key must be bytes")
        if len(data_key) != _DEK_LEN:
            raise ValueError("wrap_key data_key must be 32 bytes")
        self._require_configured()
        with self._lock:
            meta = self._registry.get(handle)
            if meta is None:
                raise ProviderUnavailable("unknown handle")
            algorithm = meta.get("algorithm")
            raw = self._unwrap_locked(meta.get("wrapped"))
        return self._wrap_dek_material(algorithm, raw, data_key)

    def rewrap_key(self, src: str, dst: str, envelope: bytes):
        """Re-wrap an envelope's data key from ``src`` to ``dst``, in-provider.

        The raw base64-decoded ``keymgr-envelope-v1`` bytes are parsed and
        structurally validated; the wrapped DEK is then authenticated and
        unwrapped under the ``src`` handle's KEK and the content GCM tag is
        verified, all inside the provider -- the DEK, the KEK private
        material and the plaintext never cross the boundary. Only the
        ``(wrapped_key, wrap_nonce)`` pair for the DST algorithm crosses it:
        AES256 yields a 48-byte AES-256-GCM sealed key and a 12-byte nonce,
        RSA2048 a 256-byte RSA-OAEP-SHA256 sealed key and ``None``. A
        ``src``/``dst`` that is not a non-empty string is a ``ValueError``;
        a non-bytes ``envelope`` a ``TypeError``; an empty or structurally,
        algorithm- or length-invalid ``envelope`` a ``ValueError``; an
        unknown handle, a ``src`` handle whose algorithm does not match the
        envelope, or corrupt stored material is
        :class:`ProviderUnavailable`; an authentication failure (wrap tag,
        OAEP padding or content tag) is :class:`ProviderInvalidMaterial`.
        """
        if not isinstance(src, str) or not src:
            raise ValueError("rewrap_key requires a non-empty src handle string")
        if not isinstance(dst, str) or not dst:
            raise ValueError("rewrap_key requires a non-empty dst handle string")
        if not isinstance(envelope, bytes):
            raise TypeError("rewrap_key envelope must be bytes")
        if not envelope:
            raise ValueError("rewrap_key envelope must be non-empty")
        self._require_configured()
        # Structural validation of the envelope payload; EnvelopeError is a
        # ValueError, exactly the contract's malformed-envelope case.
        opened = envelope_mod.parse_envelope_bytes(envelope)
        with self._lock:
            src_meta = self._registry.get(src)
            if src_meta is None:
                raise ProviderUnavailable("unknown handle")
            dst_meta = self._registry.get(dst)
            if dst_meta is None:
                raise ProviderUnavailable("unknown handle")
            src_algorithm = src_meta.get("algorithm")
            dst_algorithm = dst_meta.get("algorithm")
            if src_algorithm != opened.algorithm:
                raise ProviderUnavailable(
                    "src handle does not match the envelope algorithm"
                )
            src_raw = self._unwrap_locked(src_meta.get("wrapped"))
            dst_raw = self._unwrap_locked(dst_meta.get("wrapped"))
        dek = self._unwrap_dek_material(
            src_algorithm, src_raw, opened.wrapped_key, opened.wrap_nonce
        )
        # Authenticate the content GCM tag before re-wrapping; the recovered
        # plaintext is used only for this check and never leaves the
        # provider.
        try:
            AESGCM(dek).decrypt(
                opened.nonce, opened.ciphertext + opened.tag, opened.aad
            )
        except InvalidTag as exc:
            raise ProviderInvalidMaterial(
                "envelope content cannot be authenticated"
            ) from exc
        return self._wrap_dek_material(dst_algorithm, dst_raw, dek)


# -- module:factory loading -------------------------------------------------
_provider_lock = threading.Lock()
_provider: Optional[KeyProvider] = None
_configured_dir: Optional[str] = None
_LOCAL_SINGLETON = LocalProvider()
# Every provider_id that has been the active instance (in this process, and
# historically in the data directory) is remembered. Lets a pending operation
# distinguish a reconnect that swapped in a different provider_id (keep the op
# pending) from a record owned by a provider that was never active here (the
# classic inactive-provider terminal 503).
_active_history: set = set()
_HISTORY_NAME = "provider-ids.json"


def _history_path() -> Optional[str]:
    if _configured_dir is None:
        return None
    return os.path.join(_configured_dir, _HISTORY_NAME)


def _load_history() -> None:
    path = _history_path()
    if path is None:
        return
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except FileNotFoundError:
        return
    except (OSError, ValueError):
        return
    ids = data.get("ids") if isinstance(data, dict) else None
    if isinstance(ids, list):
        _active_history.update(i for i in ids if isinstance(i, str) and i)


def _remember(provider_id: str) -> None:
    if not provider_id or provider_id in _active_history:
        return
    _active_history.add(provider_id)
    path = _history_path()
    if path is None:
        return
    ids = sorted(_active_history)
    fd, tmp_path = tempfile.mkstemp(dir=_configured_dir, suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump({"ids": ids}, fh)
            fh.flush()
            os.fsync(fh.fileno())
        os.chmod(tmp_path, 0o600)
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        # A history write failure never blocks provider selection; the set is
        # a best-effort hint, not an authority.


# -- non-disruptive reconnect gate -----------------------------------------
# Reconnect and ordinary provider calls share ONE five-second budget per
# attempt, measured from its FIRST wait or health probe. The ordering the gate
# enforces is:
#
#   1. a reconnect first establishes a cross-process *intent* (an exclusive
#      flock on ``provider-reconnect.lock``), THEN drains the calls admitted
#      before it;
#   2. every LATER call waits -- in every process -- from the instant intent
#      is visible until the candidate is built, contract-validated, health
#      probed, ``provider-state.json`` is committed and the swap finished;
#   3. calls admitted before the intent was established keep running on the
#      OLD provider instance they captured and are simply drained.
#
# The extra intent file is required because a blocking exclusive flock alone
# is NOT a barrier on Linux: new shared-lock requests leapfrog a queued
# exclusive waiter (verified on the host kernel), so later calls would slip
# past a reconnect that had only *queued* for ``provider-state.lock`` and a
# steady call stream could starve it. Ordinary calls therefore never hold the
# intent lock for their duration; they only probe it with an instant
# non-blocking shared trylock, once before and once after taking their shared
# state lease, and fall back to waiting when the probe catches a reconnect.
CALL_GATE_SECONDS = 5.0
_POLL_SECONDS = 0.02
#: Per-probe cap for a health probe on the ORDINARY call path. One attempt's
#: probes all draw on its single non-resettable :data:`CALL_GATE_SECONDS`
#: budget as well: a probe waits at most the smaller of one second and the
#: budget remainder, and a result landing only after that wait is void.
HEALTH_PROBE_SECONDS = 1.0


class _Budget:
    """The shared five-second budget for one call or reconnect attempt.

    The deadline starts lazily at the first blocking wait OR the first
    bounded health probe (``start`` is idempotent), so an attempt admitted
    without contention spends no budget on the gate itself; every later
    wait, poll and bounded probe shares one non-resettable deadline.
    """

    def __init__(self, seconds: Optional[float] = None) -> None:
        self.seconds = CALL_GATE_SECONDS if seconds is None else seconds
        self._deadline: Optional[float] = None

    def start(self) -> float:
        if self._deadline is None:
            self._deadline = time.monotonic() + self.seconds
        return self._deadline

    @property
    def deadline(self) -> float:
        return self.start()

    def remaining(self) -> float:
        return max(0.0, self.deadline - time.monotonic())

    def expired(self) -> bool:
        return self.remaining() <= 0


class ProviderReconnectPending(ProviderUnavailable):
    """A provider call blocked on the reconnect gate past the 5 s budget.

    Like every provider failure it answers 503 with the fixed generic body,
    but an idempotent operation bound when this is raised has made NO provider
    call: the guard leaves it PENDING (mirror and binding intact, no audit

"""A fake external KMS/HSM provider for recovery tests.

Loaded through the ``module:factory`` mechanism (``KEYMGR_PROVIDER``). State
lives in a JSON file named by ``FAKE_KMS_STATE`` so several *processes* (the
CLI, a server, a recovery sweep) share one backend, exactly like a real KMS.
Fault injection is driven by a JSON file named by ``FAKE_KMS_FAULTS``:

    {
      "unreachable": true,          # every call fails as a backend outage
      "fail": {"delete": true, ...} # per-operation failures
      "sleep": {"rotate": 5.0},     # per-operation pre-call delay (seconds)
      "health": false,              # health() returns False (unavailable)
      "health_raises": true,        # health() raises (treated as unavailable)
      "health_nonbool": "yes",      # health() returns a non-bool (unavailable)
      "health_sleep": 6.0,          # health() blocks past the reconnect budget
      "provider_id": "fakekms-alt"  # override the factory's provider_id
      "declare_sign": true,         # capabilities.operations gains "sign"
      "sign_not_callable": true,    # declare sign but break the method (contract)
      "sign_short": true,           # sign() returns a malformed short value
      "sign_tamper": true,          # sign() returns a flipped-byte signature
      "declare_unwrap_key": true,   # capabilities.operations gains "unwrap_key"
      "unwrap_not_callable": true,  # declare unwrap_key but break the method
      "unwrap_fail": true,          # unwrap_key() raises a backend fault
      "unwrap_short": true,         # unwrap_key() returns a malformed short DEK
      "declare_wrap_key": true,     # capabilities.operations gains "wrap_key"
      "wrap_not_callable": true,    # declare wrap_key but break the method
      "wrap_fail": true,            # wrap_key() raises a backend fault
      "wrap_short": true            # wrap_key() returns a malformed short blob
      "declare_rewrap_key": true,   # capabilities.operations gains "rewrap_key"
      "rewrap_not_callable": true,  # declare rewrap_key but break the method
      "rewrap_fail": true,          # rewrap_key() raises a backend fault
      "rewrap_short": true          # rewrap_key() returns a malformed short blob
    }

Materials are stored base64-wrapped with a static prefix so nothing here ever
resembles plaintext, and handles are random UUIDs recorded in the state file.
Per-process per-operation call counts are exposed via ``call_count(op)`` so
tests can assert which provider operations a request actually used.
"""

import base64
import json
import os
import threading
import time
import uuid

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding

PROVIDER_ID = "fakekms"

_lock = threading.Lock()


def _state_path():
    return os.environ["FAKE_KMS_STATE"]


def _faults_path():
    return os.environ.get("FAKE_KMS_FAULTS", "")


def _load_state():
    try:
        with open(_state_path(), "r", encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return {"handles": {}}


def _save_state(state):
    path = _state_path()
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(state, fh)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, path)


def _faults():
    path = _faults_path()
    if not path:
        return {}
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


_call_counts = {}


def reset():
    """Clear per-process fault counters (called by the test fixture)."""
    _call_counts.clear()


def call_count(op):
    """How many times operation ``op`` was entered in this process."""
    return _call_counts.get(op, 0)


def _check_fault(op):
    _call_counts[op] = _call_counts.get(op, 0) + 1
    faults = _faults()
    sleep = faults.get("sleep")
    if isinstance(sleep, dict) and op in sleep:
        time.sleep(float(sleep[op]))
    if faults.get("unreachable"):
        raise RuntimeError("backend is unreachable")
    fail = faults.get("fail")
    if isinstance(fail, dict) and fail.get(op):
        raise RuntimeError("backend failure in %s" % op)
    fail_after = faults.get("fail_after")
    if isinstance(fail_after, dict) and op in fail_after:
        if _call_counts[op] > int(fail_after[op]):
            raise RuntimeError("backend failure in %s" % op)


def _wrap(material):
    return "fk1." + base64.urlsafe_b64encode(material.encode("utf-8")).decode(
        "ascii"
    )


def _unwrap(blob):
    if not isinstance(blob, str) or not blob.startswith("fk1."):
        raise RuntimeError("not a fakekms blob")
    return base64.urlsafe_b64decode(blob[4:].encode("ascii")).decode("utf-8")


class FakeKmsProvider:
    def __init__(self):
        # The id can be overridden per process (FAKE_KMS_PROVIDER_ID) so a
        # reconnect can install a provider carrying a different provider_id,
        # exercising the pending-operation displacement rule.
        self.provider_id = os.environ.get("FAKE_KMS_PROVIDER_ID", PROVIDER_ID)
        if _faults().get("sign_not_callable"):
            # Contract-violation injection: the provider declares "sign" in
            # its capabilities but the attribute is not a callable method.
            self.sign = True
        if _faults().get("unwrap_not_callable"):
            # Contract-violation injection: declares "unwrap_key" without a
            # callable method.
            self.unwrap_key = True
        if _faults().get("wrap_not_callable"):
            # Contract-violation injection: declares "wrap_key" without a
            # callable method.
            self.wrap_key = True
        if _faults().get("rewrap_not_callable"):
            # Contract-violation injection: declares "rewrap_key" without a
            # callable method.
            self.rewrap_key = True

    @property
    def capabilities(self):
        operations = [
            "generate",
            "rotate",
            "import_material",
            "export_material",
            "delete",
        ]
        if _faults().get("declare_sign"):
            operations.append("sign")
        if _faults().get("declare_unwrap_key"):
            operations.append("unwrap_key")
        if _faults().get("declare_wrap_key"):
            operations.append("wrap_key")
        if _faults().get("declare_rewrap_key"):
            operations.append("rewrap_key")
        return {
            "algorithms": ["AES256", "RSA2048"],
            "operations": operations,
        }

    def configure(self, data_dir):
        _check_fault("configure")

    def health(self):
        """Optional readiness probe driven by the faults file."""
        faults = _faults()
        if faults.get("health_raises"):
            raise RuntimeError("health endpoint is failing")
        if "health_nonbool" in faults:
            return faults.get("health_nonbool")
        if "health_sleep" in faults:
            time.sleep(float(faults["health_sleep"]))
        if "health" in faults:
            return bool(faults.get("health"))
        # Default: healthy unless the backend is globally unreachable.
        return not faults.get("unreachable")

    def _mint(self, algorithm, public_key, material):
        _check_fault("mint")
        handle = uuid.uuid4().hex
        with _lock:
            state = _load_state()
            state["handles"][handle] = {
                "algorithm": algorithm,
                "public_key": public_key,
                "material": _wrap(material),
            }
            _save_state(state)
        return {
            "handle": handle,
            "public_key": public_key,
            "encrypted_material": _wrap(material),
        }

    def generate(self, algorithm):
        _check_fault("generate")
        from keymgr.crypto import generate_key

        generated = generate_key(algorithm)
        return self._mint(
            algorithm, generated.public_material, generated.private_material
        )

    def rotate(self, algorithm):
        _check_fault("rotate")
        return self.generate(algorithm)

    def import_material(self, algorithm, public_key, material):
        _check_fault("import_material")
        if not isinstance(material, str) or not material:
            raise RuntimeError("empty material")
        return self._mint(algorithm, public_key, material)

    def export_material(self, handle):
        _check_fault("export_material")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
            if entry is None:
                raise RuntimeError("unknown handle")
            return {
                "public_key": entry["public_key"],
                "encrypted_material": _unwrap(entry["material"]),
            }

    def sign(self, handle, message):
        """Optional native RSASSA-PKCS1-v1_5/SHA-256 signature (declared via
        the ``declare_sign`` fault key)."""
        if not isinstance(handle, str) or not handle:
            raise ValueError("sign requires a non-empty handle string")
        if not isinstance(message, bytes):
            raise TypeError("sign message must be bytes")
        _check_fault("sign")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
        if entry is None:
            raise RuntimeError("unknown handle")
        if entry.get("algorithm") != "RSA2048":
            raise RuntimeError("handle is not an RSA2048 key")
        faults = _faults()
        if faults.get("sign_short"):
            # Contract-violation injection: a malformed, short signature.
            return b"short"
        private_key = serialization.load_pem_private_key(
            _unwrap(entry["material"]).encode("utf-8"), password=None
        )
        signature = private_key.sign(
            message, padding.PKCS1v15(), hashes.SHA256()
        )
        if faults.get("sign_tamper"):
            # Contract-violation injection: 256 bytes that do not verify.
            tampered = bytearray(signature)
            tampered[0] ^= 0x01
            return bytes(tampered)
        return signature

    def unwrap_key(self, handle, wrapped_key, wrap_nonce=None):
        """Optional native DEK unwrap (declared via ``declare_unwrap_key``).

        Implements the provider contract: argument ``ValueError``/
        ``TypeError`` rules, ``ProviderInvalidMaterial`` on an authentication
        failure, backend faults as plain exceptions (the service normalizes
        them to ProviderUnavailable).
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("unwrap_key requires a non-empty handle string")
        if not isinstance(wrapped_key, bytes):
            raise TypeError("unwrap_key wrapped_key must be bytes")
        if wrap_nonce is not None and not isinstance(wrap_nonce, bytes):
            raise TypeError("unwrap_key wrap_nonce must be bytes or None")
        if not wrapped_key:
            raise ValueError("unwrap_key wrapped_key must be non-empty")
        _check_fault("unwrap_key")
        if _faults().get("unwrap_fail"):
            raise RuntimeError("backend failure in unwrap_key")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
        if entry is None:
            raise RuntimeError("unknown handle")
        if _faults().get("unwrap_short"):
            # Contract-violation injection: a malformed, short data key.
            return b"short"
        from keymgr.provider import ProviderInvalidMaterial

        algorithm = entry.get("algorithm")
        material = _unwrap(entry["material"])
        if algorithm == "AES256":
            if wrap_nonce is None or len(wrap_nonce) != 12:
                raise ValueError(
                    "unwrap_key wrap_nonce must be 12 bytes for AES256"
                )
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM

            kek = base64.b64decode(material.encode("ascii"), validate=True)
            try:
                dek = AESGCM(kek).decrypt(wrap_nonce, wrapped_key, None)
            except Exception as exc:
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        elif algorithm == "RSA2048":
            if wrap_nonce is not None:
                raise ValueError(
                    "unwrap_key wrap_nonce must be null for RSA2048"
                )
            private_key = serialization.load_pem_private_key(
                material.encode("utf-8"), password=None
            )
            oaep = padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None,
            )
            try:
                dek = private_key.decrypt(wrapped_key, oaep)
            except ValueError as exc:
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        else:
            raise RuntimeError("handle is not a supported algorithm")
        if len(dek) != 32:
            raise ProviderInvalidMaterial(
                "unwrapped data key must be 32 bytes"
            )
        return dek

    def wrap_key(self, handle, data_key):
        """Optional native DEK wrap (declared via ``declare_wrap_key``).

        Implements the provider contract: argument ``ValueError``/
        ``TypeError`` rules, ``ProviderUnavailable`` for an unknown/
        algorithm-mismatched handle or a backend fault, and a success return
        of ``(wrapped_key, wrap_nonce)`` with the exact envelope shapes
        (48-byte AES-256-GCM blob + 12-byte nonce for AES256; 256-byte
        RSA-OAEP-SHA256 blob + None for RSA2048).
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("wrap_key requires a non-empty handle string")
        if not isinstance(data_key, bytes):
            raise TypeError("wrap_key data_key must be bytes")
        if len(data_key) != 32:
            raise ValueError("wrap_key data_key must be 32 bytes")
        _check_fault("wrap_key")
        if _faults().get("wrap_fail"):
            raise RuntimeError("backend failure in wrap_key")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
        if entry is None:
            raise RuntimeError("unknown handle")
        if _faults().get("wrap_short"):
            # Contract-violation injection: a malformed, short wrapped key.
            return b"short", None
        algorithm = entry.get("algorithm")
        material = _unwrap(entry["material"])
        if algorithm == "AES256":
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM

            kek = base64.b64decode(material.encode("ascii"), validate=True)
            nonce = os.urandom(12)
            wrapped = AESGCM(kek).encrypt(nonce, data_key, None)
            return wrapped, nonce
        if algorithm == "RSA2048":
            private_key = serialization.load_pem_private_key(
                material.encode("utf-8"), password=None
            )
            oaep = padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None,
            )
            wrapped = private_key.public_key().encrypt(data_key, oaep)
            return wrapped, None
        raise RuntimeError("handle is not a supported algorithm")

    def rewrap_key(self, src, dst, envelope):
        """Optional native envelope rewrap (declared via ``declare_rewrap_key``).

        Implements the provider contract: argument ``ValueError``/
        ``TypeError`` rules, structural envelope validation, in-provider
        authentication of the wrapped DEK and the content GCM tag under the
        ``src`` handle, and a re-wrap of the SAME data key under the ``dst``
        handle with the exact envelope shapes (48-byte AES-256-GCM blob +
        12-byte nonce for AES256; 256-byte RSA-OAEP-SHA256 blob + None for
        RSA2048). An authentication failure raises ProviderInvalidMaterial;
        an unknown/algorithm-mismatched handle or a backend fault raises a
        plain exception (the service normalizes it to ProviderUnavailable).
        """
        if not isinstance(src, str) or not src:
            raise ValueError("rewrap_key requires a non-empty src handle string")
        if not isinstance(dst, str) or not dst:
            raise ValueError("rewrap_key requires a non-empty dst handle string")
        if not isinstance(envelope, bytes):
            raise TypeError("rewrap_key envelope must be bytes")
        if not envelope:
            raise ValueError("rewrap_key envelope must be non-empty")
        _check_fault("rewrap_key")
        if _faults().get("rewrap_fail"):
            raise RuntimeError("backend failure in rewrap_key")
        from keymgr.envelope import parse_envelope_bytes
        from keymgr.provider import ProviderInvalidMaterial

        # Structural validation; EnvelopeError is a ValueError, the
        # contract's malformed-envelope case.
        opened = parse_envelope_bytes(envelope)
        with _lock:
            state = _load_state()
            src_entry = state["handles"].get(src)
            dst_entry = state["handles"].get(dst)
        if src_entry is None or dst_entry is None:
            raise RuntimeError("unknown handle")
        if _faults().get("rewrap_short"):
            # Contract-violation injection: a malformed, short wrapped key.
            return b"short", None
        if src_entry.get("algorithm") != opened.algorithm:
            raise RuntimeError("src handle does not match the envelope algorithm")
        src_algorithm = src_entry.get("algorithm")
        dst_algorithm = dst_entry.get("algorithm")
        src_material = _unwrap(src_entry["material"])
        dst_material = _unwrap(dst_entry["material"])
        oaep = padding.OAEP(
            mgf=padding.MGF1(algorithm=hashes.SHA256()),
            algorithm=hashes.SHA256(),
            label=None,
        )
        from cryptography.exceptions import InvalidTag
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM

        if src_algorithm == "AES256":
            kek = base64.b64decode(src_material.encode("ascii"), validate=True)
            try:
                dek = AESGCM(kek).decrypt(
                    opened.wrap_nonce, opened.wrapped_key, None
                )
            except InvalidTag as exc:
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        elif src_algorithm == "RSA2048":
            private_key = serialization.load_pem_private_key(
                src_material.encode("utf-8"), password=None
            )
            try:
                dek = private_key.decrypt(opened.wrapped_key, oaep)
            except ValueError as exc:
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        else:
            raise RuntimeError("handle is not a supported algorithm")
        if len(dek) != 32:
            raise ProviderInvalidMaterial("unwrapped data key must be 32 bytes")
        # Authenticate the content GCM tag inside the provider; the plaintext
        # never leaves this boundary.
        try:
            AESGCM(dek).decrypt(
                opened.nonce, opened.ciphertext + opened.tag, opened.aad
            )
        except InvalidTag as exc:
            raise ProviderInvalidMaterial(
                "envelope content cannot be authenticated"
            ) from exc
        if dst_algorithm == "AES256":
            kek = base64.b64decode(dst_material.encode("ascii"), validate=True)
            nonce = os.urandom(12)
            return AESGCM(kek).encrypt(nonce, dek, None), nonce
        if dst_algorithm == "RSA2048":
            private_key = serialization.load_pem_private_key(
                dst_material.encode("utf-8"), password=None
            )
            return private_key.public_key().encrypt(dek, oaep), None
        raise RuntimeError("handle is not a supported algorithm")

    def delete(self, handle):
        _check_fault("delete")
        with _lock:
            state = _load_state()
            if handle in state["handles"]:
                del state["handles"][handle]
                _save_state(state)


def make_provider():
    faults = _faults()
    if faults.get("factory_fails"):
        raise RuntimeError("fake factory is failing")
    if faults.get("factory_sleep"):
        time.sleep(float(faults["factory_sleep"]))
    return FakeKmsProvider()

def _migrate_key(self, key_id: str, parts, operator: str) -> None:
    """POST /v1/keys/{key_id}/migrate (idempotent).

    Body is exactly ``{"tenant_id": T}`` and a single
    ``Idempotency-Key`` is required, validated (with every parse/
    parameter check) BEFORE the key is bound: such failures are
    side-effect-free 400s with no audit event, operation record, key
    change or provider handle. After binding, authorization is the
    ``migrate`` policy action, an unknown/foreign key is 404, and a
    key whose versions are all already on the ready provider is 409.
    Success is ``200 {"key_id","provider_id","versions",
    "operation_id"}``: the ready provider id and the ascending version
    list. A missing/unhealthy provider, a material mismatch or a
    timeout is the fixed 503; the body never carries material or a
    handle.
    """
    idem_key = self._idempotency_key()
    if idem_key is None:
        return
    payload = self._read_json_object(audit=False)
    if payload is None:
        return
    extra = [field for field in payload if field != "tenant_id"]
    if extra:
        self._bad_request(
            "field %s is not accepted by this endpoint" % extra[0]
        )
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload, audit=False)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id, audit=False):
        return

    def execute(operation, mirror=None):
        operation_store.update_details(
            operation,
            {"kind": "migrate", "key_id": key_id},
        )
        if mirror is not None:
            mirror.describe(
                {"kind": "migrate", "write_set": [key_id]}
            )
        if not policy_store.is_allowed(
            tenant_id, audit_mod.ACTION_MIGRATE, operator
        ):
            return self._idempotent_rejection(
                operation, tenant_id, key_id,
                audit_mod.ACTION_MIGRATE, 403,
                "action not permitted by policy",
            )

        def stage_success(committed_record, provider_id, versions):
            # Runs after the rebound key file landed, before the
            # commit-point ledger append: the exact 200 body is
            # durable with the event and replayed verbatim.
            body = {
                "key_id": key_id,
                "provider_id": provider_id,
                "versions": versions,
                "operation_id": operation.operation_id,
            }
            operation_store.stage_terminal(operation, 200, body)

        try:
            result = store.migrate(
                key_id, tenant_id,
                event_id=operation.operation_id,
                lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                pre_commit=stage_success,
                mirror=mirror,
            )
        except KeyAlreadyMigrated:
            # Bound 409: every version is already on the ready
            # provider. No provider call, file change, handle or
            # success event happened; the conflict is a terminal like
            # any other bound refusal.
            return self._idempotent_rejection(
                operation, tenant_id, key_id,
                audit_mod.ACTION_MIGRATE, 409,
                "key is already managed by the ready provider",
            )
        except LockTimeout:
            # A contended key waits past the five-second budget: the
            # migrate made no provider call and wrote nothing, so keep
            # the op PENDING (mirror reset, no audit event) and answer
            # the endpoint's fixed provider 503 text; a same-key retry
            # continues under the same operation_id.
            raise ProviderReconnectPending(
                "migrate exceeded the shared five-second budget"
            )
        if result is None:
            return self._idempotent_rejection(
                operation, tenant_id, key_id,
                audit_mod.ACTION_MIGRATE, 404, "key not found",
            )
        _record, provider_id, versions = result
        return (
            200,
            {
                "key_id": key_id,
                "provider_id": provider_id,
                "versions": versions,
            },
        )

    self._idempotent_guard(
        parts.path, tenant_id, operator, payload, idem_key, execute
    )

def _decrypt_key(self, key_id: str, parts, operator: str) -> None:
    """POST /v1/keys/{key_id}/decrypt.

    Body ``{tenant_id, envelope, aad?}``. The envelope names its own
    key_id and version; both must match the request, the AAD must
    match the sealed one, and any tampering is a 400 naming the
    field. The plaintext leaves only inside the response body.
    """
    action = audit_mod.ACTION_DECRYPT
    base = self._crypto_request_base(key_id, parts, action)
    if base is None:
        return
    tenant_id, payload = base
    token = payload.get("envelope")
    if not isinstance(token, str) or not token:
        self._reject_crypto(
            tenant_id, key_id, action, 400,
            "field envelope must be a non-empty string",
        )
        return
    aad = self._request_aad(tenant_id, key_id, action, payload)
    if aad is None:
        return
    # Structural validation is parameter validation: it runs before
    # authorization, exactly like the other request fields.
    try:
        opened = envelope.decode_envelope(token)
    except envelope.EnvelopeError as exc:
        self._reject_crypto(
            tenant_id, key_id, action, 400, str(exc)
        )
        return
    if opened.key_id != key_id:
        self._reject_crypto(
            tenant_id, key_id, action, 400,
            "field envelope key_id does not match the request key_id",
        )
        return
    if not self._enforce(tenant_id, key_id, action, operator):
        return
    # Native DEK unwrap is requested by the provider, not the
    # request: when the bound provider declares unwrap_key the
    # resolve returns a NativeUnwrap pair and the KEK private
    # material never enters this process; otherwise the ordinary
    # export path yields a KEK object.
    status, record, ver, material = store.crypto_material(

        args.idempotency_key, lambda: None, execute,
        artifact_store=artifact_store,
    )

if args.command == "migrate":
    # Like rotate: the Idempotency-Key is validated before anything else;
    # a malformed key/tenant/key-id exits 2 with no audit event, operation
    # record, key change or provider handle.
    if _idem_key_error(args.idempotency_key):
        return 2
    if not args.tenant_id:
        return _fail("field tenant_id must be a non-empty string", 2)
    if not is_valid_key_id(args.key_id):
        return _fail("field key_id must be a UUID4", 2)

    body = {"tenant_id": args.tenant_id}
    path = "/v1/keys/%s/migrate" % args.key_id

    def execute(operation, mirror=None):
        op_store.update_details(
            operation,
            {"kind": "migrate", "key_id": args.key_id},
        )
        if mirror is not None:
            mirror.describe(
                {"kind": "migrate", "write_set": [args.key_id]}
            )
        if not policies.is_allowed(
            args.tenant_id, audit_mod.ACTION_MIGRATE, args.operator
        ):
            return _terminal_rejection(
                op_store, store, operation,
                args.tenant_id, args.key_id,
                audit_mod.ACTION_MIGRATE, 403,
                "action not permitted by policy",
            )

        def stage_success(committed_record, provider_id, versions):
            body = {
                "key_id": args.key_id,
                "provider_id": provider_id,
                "versions": versions,
                "operation_id": operation.operation_id,
            }
            op_store.stage_terminal(operation, 200, body)

        try:
            result = store.migrate(
                args.key_id, args.tenant_id,
                event_id=operation.operation_id,
                lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                pre_commit=stage_success,
                mirror=mirror,
            )
        except KeyAlreadyMigrated:
            return _terminal_rejection(
                op_store, store, operation,
                args.tenant_id, args.key_id,
                audit_mod.ACTION_MIGRATE, 409,
                "key is already managed by the ready provider",
            )
        except LockTimeout:
            # The migrate endpoint answers every timeout with the fixed
            # provider 503 text (CLI exit 1) and stays PENDING: no audit
            # terminal, a same-key retry continues under the same
            # operation_id.
            raise ProviderReconnectPending(
                "migrate exceeded the shared five-second budget"
            )
        if result is None:
            return _terminal_rejection(
                op_store, store, operation,
                args.tenant_id, args.key_id,
                audit_mod.ACTION_MIGRATE, 404, "key not found",
            )
        _record, provider_id, versions = result
        return (
            200,
            {
                "key_id": args.key_id,
                "provider_id": provider_id,
                "versions": versions,
            },
        )

